private readonly ConcurrentDictionary<string, TaskCompletionSource<Reply>> _pending = new();

public async Task<Reply> CallAsync(Request request, CancellationToken ct = default) {
    var id = Guid.NewGuid().ToString("N");
    var tcs = new TaskCompletionSource<Reply>(TaskCreationOptions.RunContinuationsAsynchronously);
    _pending[id] = tcs;                                  // register before sending
    await _transport.SendAsync(request with { CorrelationId = id }, ct);
    try { return await tcs.Task.WaitAsync(TimeSpan.FromSeconds(5), ct); }
    finally { _pending.TryRemove(id, out _); }
}
